"""Adopted movie population, never reuse an old movie's operator observations by fixture alone."""
import pathlib,json,gzip,hashlib,collections,sys
QA=pathlib.Path(sys.argv[1]) if len(sys.argv)>1 else pathlib.Path(__file__).resolve().parents[1];R=QA/'composition-recovery';out=pathlib.Path(sys.argv[2]) if len(sys.argv)>2 else R
def raw(p):return gzip.decompress(p.read_bytes()) if p.suffix=='.gz' else p.read_bytes()
def read(p):return json.loads(raw(p))
def sha(b):return hashlib.sha256(b).hexdigest()
summary=read(R/'final-word-source-matrix-summary.json');population=[];artifacts=[]
for selected in summary['rows']:
 case=selected['fixture'];archive='word-source-refresh-'+case if selected['observationStatus'].startswith('FRESH') else selected['finalSourceQualification']['archive'];mf=R/archive/'archive-manifest.json';m=read(mf);members={x['member']:x for x in m['files']};rowkey='matrix/'+case+'-v3-row.json';key=rowkey if rowkey in members else 'matrix/results.json';entry=members[key];data=raw(QA/entry['preserved']);assert sha(data)==entry['SHA256'];parsed=json.loads(data);rows=[parsed] if key==rowkey else parsed['rows'];actual=[r for r in rows if r['fixture']['id']==case and r['variant']=='v3'];assert len(actual)==1;r=actual[0];v=r['provenance']['finalArtifactVerification'];binding=v['binding'];expected=selected['versions']['current'];assert r['sha256']==expected['videoSHA256']==binding['videoSHA256'];assert binding['sourceCommit']==expected['sourceCommit'];assert v['status']=='MEASURED';units={u['unitId']:u for u in v['units']}
 artifacts.append({'fixture':case,'actualEncodedBinding':binding,'sourceObservationSHA256':entry['SHA256'],'artifactEvidenceId':v['evidenceId'],'finalSourceQualification':selected['observationStatus'],'unitCount':len(units),'FAVStatus':v['status']})
 for motion in v.get('motionObservations',[]):
  unit=units[motion['unitId']];obs=motion.get('intentObservation') or {};state='VERIFIED' if obs.get('status')=='MEASURED' and obs.get('passed') is True else 'FAILED' if obs.get('status')=='MEASURED' and obs.get('passed') is False else obs.get('status','UNMEASURED');identity={'binding':binding,'artifactEvidenceId':v['evidenceId'],'unitId':motion['unitId'],'fragmentIndex':motion['fragmentIndex'],'fragmentRange':motion['fragmentRange']};population.append({'evidenceId':sha(json.dumps(identity,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()),'fixture':case,**identity,'line':unit['line'],'naturalSelection':motion.get('naturalSelection') is True,'operator':motion.get('operator'),'mode':motion.get('mode'),'expectedMotion':motion.get('expectedMotion'),'operatorMeasurable':motion.get('measurable'),'rendererAgreement':{'status':motion.get('status'),'passed':motion.get('passed')},'semanticObservation':obs,'semanticState':state,'safetyEvidence':{'unitStatus':unit.get('status'),'coverage':unit.get('coverage'),'minimumContrast':unit.get('minimumContrast')},'scope':'Original complete selected movie and its actual FAV only; no fixture/row-number evidence substitution. This composite primary observation does not certify independent non-primary effects.'})
 del parsed,rows,actual,r,v,data
natural=[r for r in population if r['naturalSelection']];result={'schema':1,'releaseSourceCommit':summary['finalSourceCommit'],'artifacts':artifacts,'population':population,'primaryIntervalCount':len(population),'naturalIntervalCount':len(natural),'naturalStatuses':dict(collections.Counter(r['semanticState'] for r in natural)),'scope':'Correct actual final 30 selected movie population. Older fixed30 operator counts are historical unless videoSHA/plan/input/profile all correspond. Exact frozen Native identity is separately qualified for 23 old-source movies; source labels are unchanged.','nonPrimaryImportantEffects':'UNVERIFIED_NOT_INCLUDED_IN_THIS_PRIMARY_POPULATION','QUALITY_GO':'UNVERIFIED','human':'HUMAN_UNVERIFIED'};(out/'final-selected-primary-coverage.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print({k:result[k] for k in ['primaryIntervalCount','naturalIntervalCount','naturalStatuses']})
